// --- configuration -------------------------------------------------
// Single configuration source for the whole workflow: base URL of the
// FastAPI service (no trailing slash, no /leads) AND the lead
// qualification threshold (integer 0-100). Override them with the
// LEAD_API_BASE_URL / LEAD_QUALIFIED_THRESHOLD environment variables of
// the n8n process. n8n 2.x blocks $env in expressions and Code nodes by
// default (N8N_BLOCK_ENV_ACCESS_IN_NODE), so each lookup is probed
// defensively and falls back to the documented defaults below. The
// *Source fields record which source was used and are visible in every
// execution; downstream nodes read this configuration from this node's
// output with $('Prepare Lead Payload') - the values are never repeated
// in another node.
const DEFAULT_API_BASE_URL = 'http://localhost:8000';
// Initial business rule, NOT an empirically validated sales threshold:
// the heuristic scorer starts at a baseline of 45; representative leads
// score 12-35 (junk), 63 (corporate inbound without an intent keyword)
// and 77-100 (explicit buying intent), so 70 sits in the observed 63-77
// gap and requires net positive signal above baseline. Tune it with
// LEAD_QUALIFIED_THRESHOLD (0-100).
const DEFAULT_QUALIFIED_THRESHOLD = 70;

let apiBaseUrl = DEFAULT_API_BASE_URL;
let apiBaseUrlSource = 'workflow-default';
try {
  const fromEnv = $env.LEAD_API_BASE_URL;
  if (fromEnv) {
    apiBaseUrl = String(fromEnv).replace(/\/+$/, '');
    apiBaseUrlSource = 'environment';
  }
} catch (err) {
  // $env denied (N8N_BLOCK_ENV_ACCESS_IN_NODE) or unavailable.
  apiBaseUrlSource = 'workflow-default (n8n blocks $env access)';
}

let qualifiedThreshold = DEFAULT_QUALIFIED_THRESHOLD;
let thresholdSource = 'workflow-default';
try {
  const fromEnv = $env.LEAD_QUALIFIED_THRESHOLD;
  if (fromEnv !== undefined && fromEnv !== null && String(fromEnv).trim() !== '') {
    const parsed = Number(fromEnv);
    if (Number.isFinite(parsed) && parsed >= 0 && parsed <= 100) {
      qualifiedThreshold = parsed;
      thresholdSource = 'environment';
    } else {
      thresholdSource = 'workflow-default (invalid LEAD_QUALIFIED_THRESHOLD)';
    }
  }
} catch (err) {
  thresholdSource = 'workflow-default (n8n blocks $env access)';
}

// --- payload mapping ------------------------------------------------
// FastAPI owns validation, persistence, duplicate detection and scoring.
// This node only copies the documented contract fields out of the webhook
// body and drops everything else - no validation rules are re-implemented.
const body = $input.first().json.body || {};

const lead = {
  name: body.name ?? null,
  email: body.email ?? null,
  company: body.company ?? null,
  message: body.message ?? null,
  source: body.source || 'n8n-webhook',
  external_id: body.external_id ?? null,
};

return [{
  json: {
    lead,
    apiLeadsUrl: `${apiBaseUrl}/leads`,
    apiBaseUrlSource,
    qualifiedThreshold,
    thresholdSource,
  },
}];

// Normalize the successful (201) API response into the routing base
// result. FastAPI owns scoring - this node only copies the score it
// returned. score stays null when FastAPI could not score the lead; it
// is never coerced to 0 and never invented here.
const http = $input.first().json || {};
const body = (http.body && typeof http.body === 'object') ? http.body : {};

const rawScore = body.score;
const score = (typeof rawScore === 'number' && Number.isFinite(rawScore))
  ? rawScore
  : null;

return [{
  json: {
    apiStatus: typeof http.statusCode === 'number' ? http.statusCode : null,
    leadId: body.lead_id ?? null,
    company: body.company ?? null,
    source: body.source ?? null,
    score,
    scoreReason: body.score_reason ?? null,
  },
}];

// Qualification decision - the single place where the threshold rule is
// applied (Milestone 8). FastAPI still owns the score; this node only
// labels what FastAPI returned.
//
//   score not a finite number (null / missing)  -> manual_review, priority null
//   score >= threshold                          -> qualified,     priority "high"
//   score <  threshold                          -> not_qualified, priority "normal"
//
// The threshold comes from the configuration block of "Prepare Lead
// Payload" (one config source, never redefined here). If that config is
// missing or malformed the lead goes to manual review instead of guessing.
const config = $('Prepare Lead Payload').first().json || {};
const threshold = config.qualifiedThreshold;
const extracted = $input.first().json;
const score = extracted.score;

const thresholdOk = typeof threshold === 'number' && Number.isFinite(threshold);

let qualification;
let priority;
if (!thresholdOk || typeof score !== 'number' || !Number.isFinite(score)) {
  qualification = 'manual_review';
  priority = null;
} else if (score >= threshold) {
  qualification = 'qualified';
  priority = 'high';
} else {
  qualification = 'not_qualified';
  priority = 'normal';
}

return [{
  json: {
    ...extracted,
    qualification,
    priority,
    qualifiedThreshold: thresholdOk ? threshold : null,
    thresholdSource: config.thresholdSource ?? 'unknown',
  },
}];

// Priority routing notification for a qualified lead (Milestone 8).
// Delivery mechanism: the record below is this node's output, persisted in
// n8n's execution data and shown in the execution view. This environment
// has no email/Slack/Telegram/SMTP/CRM integration, so nothing is sent
// elsewhere and no credentials or third-party accounts are used.
const lead = $input.first().json;

return [{
  json: {
    action: 'priority_route',
    leadId: lead.leadId,
    company: lead.company,
    source: lead.source,
    score: lead.score,
    qualification: lead.qualification,
    priority: lead.priority,
    qualifiedThreshold: lead.qualifiedThreshold,
  },
}];

// Normal routing notification for a lead below the qualification
// threshold (Milestone 8). Same delivery mechanism as the priority route:
// the record is this node's output, persisted in n8n's execution data.
const lead = $input.first().json;

return [{
  json: {
    action: 'normal_route',
    leadId: lead.leadId,
    company: lead.company,
    source: lead.source,
    score: lead.score,
    qualification: lead.qualification,
    priority: lead.priority,
    qualifiedThreshold: lead.qualifiedThreshold,
  },
}];

// Manual review routing notification: FastAPI could not score the lead
// (score null) or the qualification state could not be determined
// (Milestone 8). The score is reported as null - never replaced with 0 or
// any guess. Same delivery mechanism as the other routes: this node's
// output, persisted in n8n's execution data.
const lead = $input.first().json;
const score = (typeof lead.score === 'number' && Number.isFinite(lead.score))
  ? lead.score
  : null;

return [{
  json: {
    action: 'manual_review',
    leadId: lead.leadId,
    company: lead.company,
    source: lead.source,
    score,
    qualification: lead.qualification || 'manual_review',
    priority: lead.priority ?? null,
    note: score === null
      ? 'scoring unavailable - manual review required'
      : 'qualification could not be determined - manual review required',
    qualifiedThreshold: lead.qualifiedThreshold ?? null,
  },
}];
